// 使用 DKG Signer 签名交易并提交空块，触发新区块生成
func (r *mutationResolver) StartEpoch(ctx context.Context) (bool, error) {
	// 创建空块交易
	call := &model.SysCall{
		Payload: &model.SysCall_Empty{
			Empty: time.Now().Unix(),
		},
	}

	// 提交交易
	if err := r.TeeChain.SubmitCallFromNode(call); err != nil {
		return false, gqlerror.Errorf("SubmitTx: %v", err)
	}

	return true, nil
}

// ChainInfo is the resolver for the chain_info field.
func (r *queryResolver) ChainInfo(ctx context.Context) ([]*model.ChainInfo, error) {
	chainEnv := util.GetEnv("CHAIN_ENV", "local")
	chainConfig := config.GetMainChainConfig(chainEnv)
	if chainConfig == nil {
		return nil, gqlerror.Errorf("%s", "ChainInfo is nil")
	}

	return []*model.ChainInfo{
		{
			IsMain:         true,
			SubnetContract: chainConfig.SubnetAddress,
			NetworkLabel:   chainConfig.NetworkLabel,
			ChainType:      chainConfig.ChainType,
			Urls:           chainConfig.Urls,
		},
	}, nil
}

